      if (!["issue_assigned", "comment_mention", "issue_overdue"].includes(kind)) continue;
      const allowed = channels.filter((channel) => channel !== "email");
      if (allowed.length === 0) continue;
      rows.push({ orgId, recipientId, kind, title: payload.title, body: payload.body, href: payload.href, actorId: payload.actorId, projectId: payload.projectId, channels: allowed });
      continue;
    }
    if (channels.length === 0) continue;

    rows.push({
      orgId,
      recipientId,
      kind,
      title: payload.title,
      body: payload.body,
      href: payload.href,
      actorId: payload.actorId,
      projectId: payload.projectId ?? null,
      channels,
    });
  }

  return notificationRepo.insertNotifications(orgId, rows);
}

